<?php
declare(strict_types=1);
require dirname(__DIR__).'/php-app/src/bootstrap.php';
$manifest=Annam\PublicMedia::inventory();$root=Annam\PublicMedia::root();$livePath=ANNAM_ROOT.'/resources/live-public-media-source.json';$live=is_file($livePath)?json_decode(file_get_contents($livePath),true):['failures'=>[['error'=>'Live crawl unavailable']]];$summary=Annam\PublicMedia::summary($manifest,$root);$missing=[];
