if(($summary['pending']||$summary['unavailable']||$report['discovery_failures'])&&getenv('GITHUB_STEP_SUMMARY'))file_put_contents(getenv('GITHUB_STEP_SUMMARY'),"## Original image recovery\nVerified local images: ".$summary['verified_local_images']." / ".$summary['source_assets']."\n\nSome requests could not be completed. See docs/media-recovery-report.json; missing images were not fabricated.\n",FILE_APPEND);
